        long id = json.readTree(post("/reservations", RESERVATION_JSON).body()).get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");

        HttpResponse<String> occupancy = get("/reports/occupancy?date=2027-07-11");
        assertEquals(200, occupancy.statusCode());
        assertTrue(occupancy.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
        assertTrue(occupancy.body().startsWith("Pousada Maré Alta,occupancy,2027-07-11\n"));
        assertTrue(occupancy.body().endsWith("total,1/5\n"));

        HttpResponse<String> revenue = get("/reports/revenue?month=2027-07");
        assertTrue(revenue.body().startsWith("Pousada Maré Alta,revenue,2027-07\n"));
        assertTrue(revenue.body().endsWith("total,935.76\n"));

        HttpResponse<String> tourismTax = get("/reports/tourism-tax?month=2027-07");
        assertEquals(200, tourismTax.statusCode());
        assertTrue(tourismTax.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
        assertTrue(tourismTax.body().startsWith("Pousada Maré Alta,tourism-tax,2027-07\n"));
        assertTrue(tourismTax.body().endsWith("total,27.00\n"));

        HttpResponse<String> ratePlans = get("/reports/rate-plans?month=2027-07");
        assertEquals(200, ratePlans.statusCode());
        assertTrue(ratePlans.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
        assertTrue(ratePlans.body().startsWith("Pousada Maré Alta,rate-plans,2027-07\n"));
        assertTrue(ratePlans.body().contains("STANDARD,1,935.76"));
        assertTrue(ratePlans.body().endsWith("total,1,935.76\n"));

        assertEquals(400, get("/reports/revenue?month=july").statusCode());
        assertEquals(400, get("/reports/occupancy").statusCode());
    }
}

